    "note": "SpaceX begins trading this Friday, June 12, 2026 on the Nasdaq under ticker SPCX. Priced at $135 with ~13.1B shares outstanding for a ~$1.77 trillion initial market cap, the largest IPO in history. Major defense/space contractor: Starshield, national security launches, and SDA satellite work."
